import{_ as r,o as a,c as t,ae as o}from"./chunks/framework.Dh1jimFm.js";const m=JSON.parse('{"title":"Phrase (Memsource) Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"cat-tools/phrase.md","filePath":"cat-tools/phrase.md"}'),l={name:"cat-tools/phrase.md"};function s(i,e,n,p,h,c){return a(),t("div",null,e[0]||(e[0]=[o('<h1 id="phrase-memsource-workflow" tabindex="-1">Phrase (Memsource) Workflow <a class="header-anchor" href="#phrase-memsource-workflow" aria-label="Permalink to &quot;Phrase (Memsource) Workflow&quot;">​</a></h1><p>Supervertaler supports Phrase (Memsource) bilingual DOCX round-trips.</p><h2 id="export-from-phrase" tabindex="-1">Export from Phrase <a class="header-anchor" href="#export-from-phrase" aria-label="Permalink to &quot;Export from Phrase&quot;">​</a></h2><ol><li>In Phrase Editor, go to <strong>Document → Export → Bilingual DOCX</strong></li><li>Save the file</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Supervertaler works best with two-column bilingual files (Source/Target).</p></div><h2 id="import-to-supervertaler" tabindex="-1">Import to Supervertaler <a class="header-anchor" href="#import-to-supervertaler" aria-label="Permalink to &quot;Import to Supervertaler&quot;">​</a></h2><ol><li>In Supervertaler: <strong>File → Open</strong> and select the bilingual DOCX</li><li>Translate (AI or manual) and review in the grid</li><li>Confirm segments when ready (<code>Ctrl+Enter</code>)</li></ol><h2 id="export-back-to-phrase" tabindex="-1">Export back to Phrase <a class="header-anchor" href="#export-back-to-phrase" aria-label="Permalink to &quot;Export back to Phrase&quot;">​</a></h2><ol><li>In Supervertaler: <strong>File → Export → Phrase Bilingual DOCX</strong></li><li>Save the file</li></ol><h2 id="reimport-to-phrase" tabindex="-1">Reimport to Phrase <a class="header-anchor" href="#reimport-to-phrase" aria-label="Permalink to &quot;Reimport to Phrase&quot;">​</a></h2><p>Import the bilingual DOCX back into Phrase to update the document.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Keep any tags/placeholders exactly as-is.</li><li>Don’t change the table structure in Word.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Don’t merge or split segments if you plan to reimport.</p></div>',14)]))}const d=r(l,[["render",s]]);export{m as __pageData,d as default};
